INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_DANTE_COMMEDIA','primary text','Dante Alighieri, La Divina Commedia (Inferno, Purgatorio, Paradiso, c. 1308–1321)','The structured Christian afterlife cosmos in Dante''s poem: the nine descending Circles of Hell, the seven Terraces of Mount Purgatory with ante-Purgatory and the Earthly Paradise at its summit, the nine revolving Celestial Spheres, and the Empyrean culminating in the Beatific Vision; principal medieval-poetic source for the literary topology of the Christian otherworld.'),
 ('SRC_CATECHISM_CC','reference work','Catechism of the Catholic Church (1992, rev. 1997)','Authoritative compendium of Catholic doctrine; articles on the Last Things (eschatology) defining Heaven and the Beatific Vision, Purgatory and final purification, Hell, and traditional teaching on the Limbo of the Fathers (Limbus Patrum) and the limbo of unbaptized infants.')
INSERT INTO _e VALUES
 ('ENT_CHRR_COSMOS','The Christian Cosmos','Cosmological structure','Cosmological structure','Christian','Hub node for the structured Christian afterlife and eschatological cosmos: the threefold realm of Hell, Purgatory, and Heaven, with Limbo and intermediate states, as systematized in patristic theology, medieval scholasticism, the Catechism, and given its canonical poetic form in Dante''s Divina Commedia.','B','Structural hub entity grouping the Christian otherworld realms; attested as a coherent tripartite-plus cosmos in scholastic theology and Dante.'),
 ('ENT_CHRR_PURGATORY','Purgatory','Cosmological realm','Cosmological realm','Christian','The intermediate state/place of purification for the souls of the saved who die in grace but require cleansing of temporal punishment before entering Heaven; defined doctrinally by the Catechism and councils (Lyon, Florence, Trent) and depicted by Dante as Mount Purgatory.','B','Catholic doctrine of final purification (CCC 1030–1032); poetically the seven-terraced mountain of Purgatorio.'),
 ('ENT_CHRR_LIMBUS_PATRUM','Limbo of the Fathers (Limbus Patrum)','Cosmological realm','Cosmological realm','Christian','The abode where the righteous of the Old Covenant awaited the coming of Christ, harrowed and liberated at the Descent into Hell; identified by Dante with the first circle (Limbo) and associated with the Bosom of Abraham.','B','Traditional Catholic teaching on the Harrowing of Hell; emptied by Christ at the Resurrection.'),
 ('ENT_CHRR_LIMBUS_INFANTUM','Limbo of the Infants (Limbus Infantium)','Cosmological realm','Cosmological realm','Christian','The hypothesized state/place for the souls of unbaptized infants and others dying without personal sin but without baptism, free of suffering yet excluded from the Beatific Vision; a theological theory, never defined dogma.','C','Medieval-scholastic theory (Aquinas); the Catechism leaves the fate of unbaptized infants to God''s mercy. Attested as theological tradition, not dogma.'),
 ('ENT_CHRR_EMPYREAN','The Empyrean','Cosmological realm','Cosmological realm','Christian','The highest heaven, the dwelling of God, the angels, and the blessed beyond the nine moving celestial spheres; in Dante the motionless heaven of pure light where the Celestial Rose of the saints and the Beatific Vision are beheld.','B','Medieval cosmological term (caelum empyreum); the tenth, immobile heaven in Dante''s Paradiso.'),
 ('ENT_CHRR_BEATIFIC_VISION','The Beatific Vision','Eschatological category','Eschatological category','Christian','The direct, immediate, face-to-face vision of God enjoyed by the blessed in Heaven, the supreme end and beatitude of the saved; defined doctrinally (Benedictus Deus, 1336; CCC 1028) and the culminating experience of Dante''s Paradiso.','B','Catholic doctrine of the final blessedness; distinct from the Solomonic-magic ''operation'' homonym (ENT_SOL_BEATIFIC_VISION_OP, confirmed present in DB).'),
 ('ENT_CHRR_BOSOM_ABRAHAM','The Bosom of Abraham','Cosmological realm','Cosmological realm','Christian','The place of comfort and rest for the righteous dead before the redemption, named in the parable of the rich man and Lazarus (Luke 16:22); identified in Christian tradition with the Limbo of the Fathers prior to the Harrowing of Hell.','B','Lukan parable; patristic/medieval identification with Limbus Patrum.'),
 ('ENT_CHRR_NEW_JERUSALEM','The New Jerusalem','Cosmological realm','Cosmological realm','Christian','The heavenly city descending from God in the eschaton, the consummated dwelling of God with the redeemed (Revelation 21–22); Augustine''s Civitas Dei, the perfected community of the blessed.','B','Apocalyptic vision (Rev 21); developed as the City of God by Augustine.'),
 ('ENT_CHRR_HEAVEN','Heaven','Cosmological realm','Cosmological realm','Christian','The realm of God''s eternal presence and the final blessedness of the saved, the state of perfect communion with the Holy Trinity, the angels, and the saints; the destination of the elect after particular and final judgment.','B','Core Christian eschatology (CCC 1023–1029). No prior Christian-tradition Heaven realm existed in the DB.'),
 ('ENT_CHRR_HELL','Hell (Christian)','Cosmological realm','Cosmological realm','Christian','The state and place of definitive self-exclusion from communion with God, of eternal punishment for the damned who die in mortal sin; the abode of the Devil and his demons, depicted by Dante as the nine descending circles of the Inferno.','B','Christian eschatology (CCC 1033–1037). Distinct from Jewish Gehenna/Sheol (ENT_JM_GEHENNA, ENT_ISR_SHEOL), to which it is the conceptual heir.'),
 ('ENT_CHRR_NINE_CIRCLES','The Nine Circles of Hell','Cosmological structure','Cosmological structure','Christian','Dante''s descending structure of the Inferno: Limbo, Lust, Gluttony, Greed, Wrath, Heresy, Violence, Fraud, and Treachery, ordered by gravity of sin and culminating in the frozen pit where Satan is fixed at the earth''s center.','B','Literary-structural node from Dante''s Inferno; the canonical poetic topology of Christian Hell.'),
 ('ENT_CHRR_SEVEN_TERRACES','The Seven Terraces of Mount Purgatory','Cosmological structure','Cosmological structure','Christian','Dante''s ascending structure of Purgatorio: the seven terraces purging the capital vices (Pride, Envy, Wrath, Sloth, Avarice, Gluttony, Lust), preceded by ante-Purgatory and surmounted by the Earthly Paradise at the mountain''s summit.','B','Literary-structural node from Dante''s Purgatorio; the seven terraces correspond to the seven deadly sins.'),
 ('ENT_CHRR_CELESTIAL_SPHERES','The Celestial Spheres','Cosmological structure','Cosmological structure','Christian','Dante''s ascending structure of Paradiso: the nine revolving heavens (Moon, Mercury, Venus, Sun, Mars, Jupiter, Saturn, Fixed Stars, Primum Mobile), the moving spheres of Ptolemaic-Christian cosmology through which souls ascend toward the immobile Empyrean.','B','Literary-structural node from Dante''s Paradiso, fusing Ptolemaic astronomy with Christian theology.');
