INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_CHRR_HEAVEN','member_of','ENT_CHRR_COSMOS','high','Heaven is a principal realm of the structured Christian cosmos.'),
 ('ENT_CHRR_HELL','member_of','ENT_CHRR_COSMOS','high','Hell is a principal realm of the structured Christian cosmos.'),
 ('ENT_CHRR_PURGATORY','member_of','ENT_CHRR_COSMOS','high','Purgatory is the intermediate purifying realm of the Christian cosmos.'),
 ('ENT_CHRR_LIMBUS_PATRUM','member_of','ENT_CHRR_COSMOS','high','The Limbo of the Fathers is a region of the Christian otherworld cosmos.'),
 ('ENT_CHRR_LIMBUS_INFANTUM','member_of','ENT_CHRR_COSMOS','medium','The Limbo of the Infants is a theorized region of the Christian cosmos.'),
 ('ENT_CHRR_EMPYREAN','member_of','ENT_CHRR_HEAVEN','high','The Empyrean is the highest heaven, the innermost dwelling of God within Heaven.'),
 ('ENT_CHRR_NEW_JERUSALEM','member_of','ENT_CHRR_HEAVEN','high','The New Jerusalem is the consummated heavenly city, the perfected form of Heaven.'),
 ('ENT_CHRR_BOSOM_ABRAHAM','equated_with','ENT_CHRR_LIMBUS_PATRUM','high','Christian tradition identifies the Bosom of Abraham with the Limbo of the Fathers, the rest of the righteous dead before Christ.'),
 ('ENT_CHRR_BEATIFIC_VISION','dwells_in','ENT_CHRR_EMPYREAN','medium','The Beatific Vision is enjoyed by the blessed in the Empyrean, the highest heaven.'),
 ('ENT_CHRR_NINE_CIRCLES','member_of','ENT_CHRR_HELL','high','Dante''s nine descending circles are the structural articulation of Hell.'),
 ('ENT_CHRR_SEVEN_TERRACES','member_of','ENT_CHRR_PURGATORY','high','Dante''s seven terraces are the structural articulation of Mount Purgatory.'),
 ('ENT_CHRR_CELESTIAL_SPHERES','member_of','ENT_CHRR_HEAVEN','high','Dante''s nine revolving celestial spheres are the ascending structure of Heaven below the Empyrean.'),
 ('ENT_CHRR_LIMBUS_PATRUM','member_of','ENT_CHRR_NINE_CIRCLES','medium','Dante places Limbo as the first of the nine circles of Hell.'),
 ('ENT_CHR_DEVIL','dwells_in','ENT_CHRR_HELL','high','Hell is the abode of the Devil; Dante fixes Satan at the center of the Inferno.'),
 ('ENT_CHR_DEMONS','dwells_in','ENT_CHRR_HELL','high','The demons inhabit Hell with their prince the Devil.'),
 ('ENT_JESUS_CHRIST','rescues','ENT_CHRR_LIMBUS_PATRUM','high','In the Harrowing of Hell, Christ descends and liberates the righteous held in the Limbo of the Fathers.'),
 ('ENT_CHRR_HELL','reception_of','ENT_JM_GEHENNA','medium','The Christian conception of Hell as the place of eternal punishment develops from the Jewish Gehenna.'),
 ('ENT_CHRR_BOSOM_ABRAHAM','reception_of','ENT_ISR_SHEOL','low','The Bosom of Abraham as the rest of the righteous dead draws on the older Israelite Sheol as abode of the dead.'),
 ('ENT_PAT_AUGUSTINE','transmits','ENT_CHRR_NEW_JERUSALEM','medium','Augustine systematizes and transmits the heavenly Jerusalem as the City of God in De Civitate Dei.');
